import functools as _mk_ft   # v272: pamięć postaci kluczy (biblioteka standardowa)


@_mk_ft.lru_cache(maxsize=256)
def _mask_formy(k, kawalki=False):
    """v272 (przegląd v271): postaci wartości sekretu, w których może się pojawić w komunikacie — dosłowna, z ucieczkami (repr: \\t, \\n;
    JSON: \\u0000) i zakodowana w adresie (%09, +); kawalki=True (klucz odrzucony przez klucz()) — także każdy kawałek ≥ 6 znaków między
    spacjami i znakami sterującymi (inna biblioteka mogła zakodować tylko sam znak). Najdłuższe najpierw."""
    f = {k, repr(k)[1:-1], json.dumps(k)[1:-1], urllib.parse.quote(k, safe=''), urllib.parse.quote_plus(k)}
    if kawalki:   # v278 (przegląd v272): nazwa zmiennej wklejona z wartością („FMP_KEY = …”) nie jest kawałkiem klucza — inaczej „Klucz ***” w meta
        f.update(p for p in _KLUCZ_ZLY.split(k) if len(p) >= 6 and not re.fullmatch(r'[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)*_(?:KEY|TOKEN|SECRET)', p))
    return tuple(sorted((x for x in f if x), key=len, reverse=True))


def mask(text):
    """Komunikat błędu nigdy nie zawiera klucza (nawet gdy dostawca odbije adres z parametrem, także w postaci z ucieczkami — v272)."""
    text = str(text)
    for k in SECRETS:
        if k:
            for x in _mask_formy(k):
                text = text.replace(x, '***')
    for k in SECRETS_ZLE:
        for x in _mask_formy(k, True):
            text = text.replace(x, '***')
    return text


def klucz(name):
    """v272 (przegląd v271): sekret ze zmiennej środowiska (GitHub Secrets) bez spacji na końcach. Spacja, tabulator, nowa linia albo inny
    znak sterujący W ŚRODKU (np. sekret wklejony w dwóch liniach) = klucz nieużyty + błąd w meta (tylko nazwa, nigdy wartość): zapytanie z takim
    kluczem i tak by się nie udało, a komunikat biblioteki cytowałby adres z kluczem w postaci z ucieczkami. Wartość zostaje w SECRETS_ZLE
    (maskowana z kawałkami)."""
    v = os.environ.get(name, '').strip()
    if v and _KLUCZ_ZLY.search(v):
        if v not in SECRETS_ZLE:
            SECRETS_ZLE.append(v)
        META['errors'].append(f'Klucz {name}: spacja albo znak sterujący (np. nowa linia) w środku wartości — klucz nieużyty; popraw sekret w GitHub')
        return ''
    return v


import threading as _zuz_th, urllib.parse as _zuz_parse   # v222: blokada licznika (części w wątkach) i rozbiór adresu (biblioteka standardowa)

ZUZ_PLANY = {'cg': ('api.coingecko.com', 'x-cg-demo-api-key'),   # v222: darmowe plany z limitem — host i nagłówek klucza (bez klucza = nie z planu)
             'cmc': ('pro-api.coinmarketcap.com', None),
             'td': ('api.twelvedata.com', None)}                # Twelve Data: kredyty = liczba symboli w zapytaniu
ZUZ_DOST_H = 6        # v222: raport zużycia od dostawcy (CoinMarketCap) najwyżej raz na blok 6 godzin UTC
_ZUZ = {}             # v222: zapytania tego przebiegu do planów z limitem (td: kredyty)
_ZUZ_LOCK = _zuz_th.Lock()


def _zuz_licz(url, headers=None):
    """v222: zapytanie do darmowego planu z limitem → licznik tego przebiegu. CoinGecko tylko z kluczem w nagłówku (zapytanie bez klucza nie
    zużywa planu), Twelve Data: kredyty = liczba symboli w parametrze symbol. Licznik nigdy nie przerywa zapytania."""
    try:
        u = _zuz_parse.urlsplit(url)
        for k, (host, hdr) in ZUZ_PLANY.items():
            if u.hostname != host:
                continue
            if hdr and not any(str(h).lower() == hdr and v for h, v in (headers or {}).items()):
                return
            n = 1
            if k == 'td':
                s = _zuz_parse.parse_qs(u.query).get('symbol')
                n = max(1, len([x for x in s[0].split(',') if x.strip()])) if s else 1
            with _ZUZ_LOCK:
                _ZUZ[k] = _ZUZ.get(k, 0) + n
            return
    except Exception:
        return


import http.client as _http_client   # v272: InvalidURL (biblioteka standardowa; ponowny import jest nieszkodliwy)


def _otworz(url, headers=None, timeout=30):
    """v272 (przegląd v271): żądanie GET z identyfikatorem zbieracza. Zły adres albo nagłówek (np. znak sterujący w kluczu) = ValueError bez
    treści — komunikat biblioteki (http.client.InvalidURL, „Invalid header value”, „unknown url type”) cytuje cały adres albo nagłówek, a w nim
    klucz w postaci z ucieczkami (\\t, \\n); „from None” — także bez pierwotnego wyjątku w śladzie w dzienniku przebiegu."""
    try:
        return urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'CapitalFlowAI-collector/1.0', **(headers or {})}),
                                      timeout=timeout)
    except (ValueError, _http_client.InvalidURL) as e:   # InvalidURL nie jest ValueError (http.client.HTTPException)
        raise ValueError(f'zły adres albo nagłówek zapytania ({type(e).__name__})') from None


def get(url, headers=None, timeout=30):
    _zuz_licz(url, headers)   # v222: licznik zużycia planów z limitem
    with _otworz(url, headers, timeout) as r:   # v272: zły adres/nagłówek — komunikat bez klucza
        return r.status, r.read().decode('utf-8', 'replace')


def get_json(url, headers=None, timeout=30):
    st, body = get(url, headers, timeout)
    return json.loads(body)


def get_bytes(url, headers=None, timeout=60):
    _zuz_licz(url, headers)   # v222: licznik zużycia planów z limitem
    with _otworz(url, headers, timeout) as r:   # v272: zły adres/nagłówek — komunikat bez klucza
        return r.read()


def soso(path, key, _retry=True):
    time.sleep(SOSO_SLEEP)
    try:
        j = get_json(SOSO + path, {'x-soso-api-key': key})
    except urllib.error.HTTPError as e:
        if e.code == 429 and _retry and (_DEADLINE[0] is None or time.monotonic() < _DEADLINE[0]):          # limit minutowy — odczekaj pełną minutę i spróbuj raz jeszcze
            print('SoSoValue 429 — czekam 65 s')
            time.sleep(65)
            return soso(path, key, _retry=False)
        raise
    if isinstance(j, dict) and j.get('code') not in (None, 0):
        raise RuntimeError(f'SoSoValue {path}: {j.get("message")}')
    return j['data'] if isinstance(j, dict) and 'data' in j else j


def _prev_site(name):
    site = os.environ.get('SITE_URL', '').rstrip('/')
    if not site:
        return None
    try:
        return get_json(f'{site}/data/{name}.json?t={int(time.time())}')
    except urllib.error.HTTPError as e:
        if e.code == 404:   # pliku jeszcze nie ma (pierwszy przebieg) — informacja, nie błąd
            META['notes'].append(f'poprzedni {name}.json: brak na stronie (404)'); return None
        META['errors'].append(mask(f'poprzedni {name}.json: {e}')); return None
    except Exception as e:  # noqa
        META['errors'].append(mask(f'poprzedni {name}.json: {e}'))
        return None


def _prev_cache(name):
    """v51: plik z pamięci GitHub Actions (CACHE_DIR) — przeżywa awarię publikacji strony."""
    d = os.environ.get('CACHE_DIR', '').strip()
    if not d:
        return None
    p = os.path.join(d, name + '.json')
    if not os.path.exists(p):
        return None
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:  # noqa
        META['errors'].append(mask(f'pamięć {name}.json: {e}'))
        return None


def previous(name):
    """Poprzedni plik: nowszy (wg pola at) z pamięci Actions i z opublikowanej strony — awaria API nie wymaże danych,
    a awaria publikacji nie zwielokrotni zapytań (v51)."""
    cands = [c for c in (_prev_cache(name), _prev_site(name)) if isinstance(c, dict)]
    if not cands:
        return None
    # v132: remis pola at (plik bez nowych danych, np. sama zmiana licznika prób SOPR) rozstrzyga czas przebiegu run.at — stara kopia z pamięci
    # Actions nie cofa licznika; pliki bez run.at jak dotąd (przy remisie pierwsza: pamięć Actions)
    return max(cands, key=lambda c: (str(c.get('at') or ''), str(c['run'].get('at') or '') if isinstance(c.get('run'), dict) else ''))


def fresh(prev, minutes):
    """Czy poprzedni plik (z opublikowanej strony) jest młodszy niż `minutes` minut."""
    try:
        at = datetime.datetime.fromisoformat(prev['at'])
        return (datetime.datetime.now(datetime.timezone.utc) - at).total_seconds() < minutes * 60
    except Exception:
        return False


def save(name, obj):
    os.makedirs(OUT, exist_ok=True)
    with open(f'{OUT}/{name}.json', 'w', encoding='utf-8') as f:
        json.dump(obj, f, ensure_ascii=False, separators=(',', ':'))
    SAVED[name] = obj
    if _RUN_T0[0] is not None:   # v185: chwila zapisu (sekundy od startu przebiegu) — czas części przebiegu do meta.json i kontroli
        _CZAS.append((name, time.monotonic() - _RUN_T0[0]))
    print(f'zapisano {OUT}/{name}.json ({os.path.getsize(f"{OUT}/{name}.json")} B)')


def ts(date_str):
    return int(datetime.datetime.strptime(date_str, '%Y-%m-%d').replace(tzinfo=datetime.timezone.utc).timestamp())


